options.systemMessage:
Você qualifica leads comerciais recebidos pelo WhatsApp.

Retorne SOMENTE um objeto JSON, sem prosa e sem bloco markdown, exatamente com estas chaves:
{"intencao": string, "orcamento_mencionado": boolean, "prazo_mencionado": boolean, "temperatura": "quente" | "morno" | "frio", "resposta": string}

Critérios de temperatura:
- quente: descreve uma necessidade concreta E menciona orçamento, prazo ou pede para falar com uma pessoa;
- morno: faz uma pergunta real sobre o produto, mas sem sinal de urgência;
- frio: somente cumprimento, número errado, spam ou assunto sem relação.

`resposta` será enviada à pessoa. Use no máximo 2 frases curtas, sem markdown e no mesmo idioma da mensagem recebida. Para lead quente, diga que uma pessoa da equipe continuará o atendimento em breve. Nunca invente preço, prazo, política ou capacidade do produto.

parameters.jsCode:
// Aceita apenas o contrato JSON esperado e usa um fallback seguro.
// Um modelo que responda mal não deve derrubar nem perder o lead.
const raw = String($input.first().json.output ?? '').trim();
const lead = $('Webhook Wafly').first().json.body || {};
const cfg = $('Configuração').first().json;

const fallback = {
  intencao: 'nao_classificada',
  orcamento_mencionado: false,
  prazo_mencionado: false,
  temperatura: 'morno',
  resposta: 'Obrigado pela mensagem. Pode contar um pouco mais sobre o que você precisa?',
};

let parsed = { ...fallback };
try {
  const cleaned = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const candidate = JSON.parse(cleaned);
  if (candidate && typeof candidate === 'object' && !Array.isArray(candidate)) {
    parsed = { ...fallback, ...candidate };
  }
} catch (error) {
  // Mantém o fallback.
}

parsed.temperatura = String(parsed.temperatura || '').toLowerCase();
if (!['quente', 'morno', 'frio'].includes(parsed.temperatura)) parsed.temperatura = 'morno';
parsed.intencao = String(parsed.intencao || fallback.intencao).trim().slice(0, 240);
parsed.resposta = String(parsed.resposta || fallback.resposta).trim().slice(0, 500) || fallback.resposta;
parsed.orcamento_mencionado = parsed.orcamento_mencionado === true;
parsed.prazo_mencionado = parsed.prazo_mencionado === true;

const salesPhone = String(cfg.salesPhone || '').replace(/\D/g, '');
if (salesPhone.length < 10) {
  throw new Error('Configure salesPhone no nó Configuração usando somente números e incluindo o DDI.');
}
const leadPhone = String(lead.phone || '').replace(/\D/g, '');
if (leadPhone.length < 10) {
  throw new Error('O webhook recebido não contém um telefone válido em body.phone.');
}

return [{
  json: {
    ...parsed,
    leadPhone,
    leadName: lead.senderName || lead.chatName || 'Não informado',
    leadMessage: lead.text?.message || '',
    salesPhone,
    parsedOk: parsed.intencao !== fallback.intencao,
    templateId: 'n8n-08-qualificar-leads',
  },
}];

